fn replace_chars(s: &[char], old: char, new: char) -> Vec<char> {
    let mut result = Vec::with_capacity(s.len()); // Preallocate memory for efficiency

    for &c in s {
        if c == old {
            result.push(new); // Replace with new character
        } else {
            result.push(c); // Keep the original character
        }
    }

    result // Return the new vector
}